"""Vocabulary for the stand-alone garment system (garment_build.py): structural attributes of garments (necklines, sleeves, hems, waists, leg shapes ...),
base garment names and extra garment names.  Nothing here mentions a colour, a gender or an age."""
import itertools
from vocab_lib import S, sample

def prod(a, b, fmt, n, name, skip_same=False):
    out = [fmt.format(x, y).strip(' ,') for x in a for y in b if not (skip_same and x == y)]
    return sample(sorted(set(out)), n, name)

