FEAT = S("a pleated front, a gathered back, a smocked panel, a yoke across the shoulders, a back vent, a box pleat at the back, princess seams, darts at the bust and waist, a side panel in a different weave, a lace panel, a mesh panel, a ribbed panel, a tie at the waist, a detachable belt, a removable hood, a ruffle trim, a peplum, a hem band, a godet insert, a contrast yoke, shoulder epaulettes, elbow patches, a double layer, a gathered hem")

def attr_files():
    A = {}
    A['garment_neckline'] = prod(NECK_M, NECK, '{0} {1}', 360, 'g_neck') + NECK
    A['garment_sleeve'] = prod(SLEEVE, CUFF, '{0} with {1}', 300, 'g_sleeve') + SLEEVE + SLEEVELESS
    A['garment_length'] = prod(S("ends, falls, hangs, reaches, sits, finishes, stops, skims"), S("at the waist, just below the waist, at the hip, at mid-thigh, above the knee, at the knee, just below the knee, at mid-calf, at the ankle, just above the ankle, at the floor, with a short train, at the upper thigh, at the lower hip, below the seat, at the shin"), '{0} {1}', 200, 'g_len') + [f"{a} {x}" for a in ('cut to a', 'made in a', 'finished at a') for x in LENGTH if x != 'short'][:0] + [x if x.endswith('length') else x + ' length' for x in LENGTH]
    _l = A['garment_length']; A['garment_length'] = list(dict.fromkeys(_l + prod(S("neatly, softly, comfortably, deliberately, just"), _l, '{0} {1}', 150, 'g_len2')))
    A['garment_hem'] = prod(S("clean, deep, narrow, soft, curved, sharp, stitched, machine-finished, hand-finished, weighted, light"), HEM, '{0} {1}', 260, 'g_hem') + HEM
    A['garment_waist'] = prod(WAIST, WAIST_M, '{0} {1}', 300, 'g_waist') + WAIST
    A['garment_leg'] = prod(LEG, LEG_M, '{0} with a {1}', 300, 'g_leg') + LEG
    A['garment_silhouette'] = prod(SIL, SIL_M, '{0} silhouette {1}', 300, 'g_sil') + [x + ' silhouette' for x in SIL]
    A['garment_closure'] = prod(CLOSE, CLOSE_M, '{0} {1}', 300, 'g_close') + CLOSE
    A['garment_pockets'] = prod(POCK, POCK_M, '{0} {1}', 300, 'g_pock') + POCK
    A['garment_collar'] = prod(COLLAR, COLLAR_M, '{0} {1}', 280, 'g_coll') + COLLAR
    A['garment_lining'] = prod(LINING, LINING_M, '{0} {1}', 260, 'g_lin') + LINING
    A['garment_feature'] = prod(FEAT, S("at the front, at the back, at the side, along the seam, across the chest, around the hem, at the waist, at the shoulder, at the cuff, on one side"), '{0} {1}', 240, 'g_feat') + FEAT
    return {k: list(dict.fromkeys(v)) for k, v in A.items()}

