# ------------------------------------------------------------------ extra garment names for the small groups (to reach 200+ distinct)
def extra_names(key, base_list, mods, n):
    pre = S("high-waisted, low-slung, relaxed, tailored, vintage-style, oversized, fitted, cropped, longline, lightweight, heavyweight, structured, slouchy, minimalist, boxy, tapered, layered, utilitarian, romantic, sporty, workwear-style, retro, modern, classic, handmade, reversible, pleated, panelled, quilted, ruched, draped, tiered, belted, hooded, collared, asymmetric, double-layered, wrap-front, button-front, zip-front, drawstring")
    post = S("with a contrast yoke, with patch pockets, with piped seams, with a pleated back, with side slits, with a gathered hem, with exposed stitching, with a hidden placket, with a removable belt, with a double row of buttons, with a back vent, with tonal topstitching, with deep side pockets, with an adjustable waist, with a raw edge, with a lined hem, with elbow patches, with a draped front, with a folded cuff, with metal eyelets")
    items = {f'{a} {b}' for a in pre for b in base_list} | {f'{b} {c}' for b in base_list for c in post} | {f'{a} {b} {c}' for a in pre[::3] for b in base_list for c in post[::4]}
    return sample(sorted(items), n, 'xn_' + key)

PRE_BASE = S("relaxed, tailored, vintage-style, oversized, fitted, lightweight, heavyweight, structured, slouchy, minimalist, boxy, utilitarian, romantic, sporty, workwear-style, retro, modern, classic, handmade, reversible, panelled, quilted, ruched, draped, belted, hooded, asymmetric, double-layered, everyday, dressy, rugged, delicate, bohemian, preppy, streetwear, artisan, tech-fabric, casual, formal, crisp, soft, rustic, urban, resort, theatrical, heritage, avant-garde, sculptural, airy, cosy")
def base_variants(key, bases, n):
    items = list(bases) + [f"{a} {b}" for a in PRE_BASE for b in bases]
    return sample(items, n, 'bv_' + key) if len(items) > n else items
